27	/**
28	 * Programmatic "(location) (service)" marketing landing pages, the region-tier
29	 * umbrella pages above them, AND (added here) the game-family × location
30	 * matrix + the general per-location VPS/Game-Server pages that don't already
31	 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
32	 * file doc for the full architecture note.
33	 *
34	 * Four data tables, one route: a slug is checked against the region matrix,
35	 * then the city matrix, then the game×location matrix, then the general
36	 * new-location matrix — in that order, so nothing here can ever shadow a
37	 * hand-written static marketing page (which wins at request time anyway) or
38	 * silently collide with an existing slug. Anything in none of the four falls
39	 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
40	 * that family's real `GamePlan` rows) feed every page's pricing grid and
41	 * Product rich-result — nothing here is a hardcoded price.
42	 */
43	
44	export const dynamic = "force-dynamic";
45	
46	// Pre-declare every known slug across all four tables so Next can enumerate
47	// them at build time; unknown slugs are rejected in the page/metadata via
48	// notFound().
49	export function generateStaticParams(): Array<{ slug: string }> {
50	  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
51	    slug,
52	  }));
53	}
54	
55	async function loadVpsPlans(): Promise<LandingPlan[]> {
56	  return db.plan.findMany({
57	    where: { active: true },
58	    orderBy: { sortOrder: "asc" },
59	  });
60	}
61	
62	/**
63	 * Real, active `GamePlan` rows for one family, mapped both to the plain
64	 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
65	 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
66	 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
67	 * server is provisioned on), never a fabricated number.
68	 */
69	async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
70	  const plans = await db.gamePlan.findMany({
71	    where: { gameFamily, active: true },
72	    orderBy: { sortOrder: "asc" },
73	    include: { basePlan: true },
74	  });
75	  const rows: GamePlanRow[] = plans.map((p) => ({
76	    id: p.id,
77	    name: p.name,
78	    ramMB: p.ramMB,
79	    slots: p.slots,
80	    priceCents: p.priceCents,
81	    introPriceCents: p.introPriceCents,
82	  }));
83	  const cards: PlanCard[] = plans.map((p) => ({
84	    id: p.id,
85	    name: p.name,
86	    cpuCores: p.cpuCores,
87	    ramMB: p.ramMB,
88	    diskGB: p.diskGB,
89	    bandwidthTB: p.basePlan.bandwidthTB,
90	    priceCents: p.priceCents,
91	    storageTier: p.basePlan.storageTier,
92	    introMonthlyCents: p.introPriceCents,
93	    slots: p.slots,
94	  }));
95	  return { rows, cards };
96	}
97	
98	/**
99	 * Discriminant is NOT "does this page's service key happen to be `game`" —
100	 * the pre-existing city/region/general-location "game server hosting" pages
101	 * (e.g. "toronto-game-server-hosting") already price themselves off generic
102	 * VPS `Plan` rows (same as every other service on those tables) and deploy
103	 * as `service=vps`, unchanged from before this file existed. Only a genuine
104	 * per-family combo (e.g. "singapore-minecraft-server-hosting", resolved via
105	 * `findGameLocationCombo`) prices off that family's real `GamePlan` rows and
106	 * needs `service="game"` + `gameFamily` wired through to the deploy links.
107	 */
108	type Resolved =
109	  | { kind: "generic"; built: BuiltLanding; plans: LandingPlan[] }
110	  | { kind: "game-family"; built: BuiltLanding; plans: PlanCard[]; gameFamily: string; productName: string };
111	
112	async function resolve(slug: string): Promise<Resolved | undefined> {
113	  const regionCombo = findRegionCombo(slug);
114	  if (regionCombo) {
115	    const plans = await loadVpsPlans();
116	    return { kind: "generic", built: buildRegionLanding(regionCombo, plans), plans };
117	  }
118	
119	  const combo = findCombo(slug);
120	  if (combo) {
121	    const plans = await loadVpsPlans();
122	    return { kind: "generic", built: buildLanding(combo, plans), plans };
123	  }
124	
125	  const generalCombo = findGeneralLocationCombo(slug);
126	  if (generalCombo) {
127	    const plans = await loadVpsPlans();
128	    return { kind: "generic", built: buildGeneralLocationLanding(generalCombo, plans), plans };
129	  }
130	
131	  const gameCombo = findGameLocationCombo(slug);
132	  if (gameCombo) {
133	    const { rows, cards } = await loadGamePlans(gameCombo.family);
134	    const built = buildGameLocationLanding(gameCombo, rows);
135	    return { kind: "game-family", built, plans: cards, gameFamily: built.gameFamily, productName: built.productName };
136	  }
137	
138	  return undefined;
139	}
