151	  const url = `${APP_URL}/${slug}`;
152	
153	  return {
154	    title: built.metaTitle,
155	    description: built.metaDescription,
156	    alternates: { canonical: `/${slug}` },
157	    openGraph: {
158	      type: "article",
159	      title: built.ogTitle,
160	      description: built.ogDescription,
161	      url,
162	    },
