199	        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
200	      />
201	      <UseCaseLanding
202	        content={built.content}
203	        plans={plans as PlanCard[]}
204	        service={resolved.kind === "game-family" ? "game" : "vps"}
205	        gameFamily={resolved.kind === "game-family" ? resolved.gameFamily : undefined}
206	        productName={resolved.kind === "game-family" ? resolved.productName : undefined}
207	        pageUrl={url}
