import type { GameFamily } from "@/lib/games";
import { GAME_DISPLAY, GAME_GENRES } from "@/lib/games";
import { flagEmoji } from "@/lib/flag-emoji";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import {
  listPhrase,
  SERVICES,
  type BuiltLanding,
  type LandingPlan,
  type ServiceKey,
} from "@/lib/marketing/locationLandings";
import { PREVIEW_GAMES, type PreviewGame, type PreviewPlan, type PreviewGameKey } from "@/components/marketing/gamelanding/data";
import type { PlanCard } from "@/components/marketing/PricingGrid";

/* ------------------------------------------------------------------ */
/* GameLandingCombined adapter (2026-09-19) — renders game×location      */
/* combos through the SAME flagship template as the ~40 hand-built      */
/* per-game pages, instead of the generic UseCaseLanding/PricingGrid    */
/* path above. See the file doc at the top: `buildGameLocationLanding`  */
/* above still exists (its FAQ/related/JSON-LD content is reused below, */
/* just not its own `useCaseContent` hero/intro/why/steps rendering).   */
/* ------------------------------------------------------------------ */

/** This location's nearest REAL Nxeon region key (sgp1/fsn1), or undefined
 * when neither is honestly closer (the "market" locations — US/NA/Canada) —
 * passed to `deployHref({ region })` so the wizard can pre-select it without
 * ever implying a region that isn't genuinely the better round-trip. Derived
 * from the exact same geography-grounded `presence` reasoning already
 * documented on `GAME_LOCATIONS` above (Singapore/SEA/network-Asia → sgp1,
 * Germany/Europe/network-Europe → fsn1), not a new judgment call. */
function nearestRealRegion(loc: GameLocationDef): "sgp1" | "fsn1" | undefined {
  const sgSide = new Set(["singapore", "southeast-asia", "south-korea", "japan", "malaysia", "indonesia", "india", "australia"]);
  const deSide = new Set(["germany", "europe", "united-kingdom", "netherlands"]);
  if (sgSide.has(loc.slug)) return "sgp1";
  if (deSide.has(loc.slug)) return "fsn1";
  return undefined; // united-states, north-america, canada — genuinely no honest answer
}

/** Hero trust-strip chip text, replacing "Singapore · low latency" — honest per `presence`. */
function trustStripLabel(loc: GameLocationDef): string {
  if (loc.presence === "datacenter") return `${loc.name} · real datacenter`;
  if (loc.presence === "network") return `${loc.name} · low-latency network`;
  return `${loc.name} audience · served from SG/DE`;
}

/** HUD deploy-beat region tag, replacing the hardcoded "Singapore · sgp1". */
function regionTagLabel(loc: GameLocationDef): string {
  const region = nearestRealRegion(loc);
  if (region) return `${REGION_LABELS_LOCAL[region]} · ${region}`;
  return "Singapore or Germany";
}
const REGION_LABELS_LOCAL: Record<"sgp1" | "fsn1", string> = { sgp1: "Singapore", fsn1: "Falkenstein, DE" };

/** Short, honest, position-derived tier label — real GamePlan rows don't carry
 * a flavor-name like PREVIEW_GAMES' "Starter wipe"/"Community"/"Big wipe", so
 * this reads off the ladder position instead of inventing per-tier prose. */
function tierLabel(idx: number, n: number): string {
  if (n <= 1) return "Standard";
  if (idx === 0) return "Starter";
  if (idx === n - 1) return "Pro";
  return "Standard";
}

/** Real-data-only feature list for a game plan card — mirrors PricingGrid.tsx's
 * own `planFeatures(p, "game")` (slots headline, then real spec, FTP, DDoS);
 * duplicated in miniature here rather than importing a private helper from a
 * "use client" component into this server-safe data module. */
function gamePlanFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    ...(p.slots ? [`${p.slots} player slots`] : []),
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    "Full file access (FTP)",
    "Free DDoS protection",
  ];
}

/**
 * Real `GamePlan`/basePlan rows (`cards`, already fetched by the route for the
 * pricing grid) mapped into `PreviewPlan[]` — the shape GameLandingCombined's
 * plan cards and configurator actually read. Every number is real: price and
 * intro price from `priceCents`/`introPriceCents` (via the same
 * `planIntroMonthlyCents` helper the rest of the site's intro-pricing display
 * uses), RAM/CPU/disk/slots from the row itself. Nothing here is fabricated —
 * `blurb`/`tier`/`features` are derived text, not invented numbers.
 */
function buildRealPreviewPlans(gameName: string, cards: PlanCard[]): PreviewPlan[] {
  const popularIdx = cards.length ? Math.floor((cards.length - 1) / 2) : -1;
  return cards.map((p, i) => {
    const introCents = planIntroMonthlyCents(p);
    const hasIntro = introCents != null;
    return {
      id: p.id,
      tier: tierLabel(i, cards.length),
      ram: `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB`,
      price: money(hasIntro ? introCents! : p.priceCents),
      renewalPrice: hasIntro ? money(p.priceCents) : undefined,
      meta: p.slots ? `${p.slots} slots` : `${p.cpuCores} vCPU · ${p.diskGB} GB NVMe`,
      slots: p.slots ?? undefined,
      blurb: p.slots
        ? `A dedicated ${gameName} server sized for up to ${p.slots} concurrent players.`
        : `A dedicated ${gameName} server with ${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM and ${p.diskGB} GB NVMe.`,
      popular: i === popularIdx,
      features: gamePlanFeatures(p),
    };
  });
}

/**
 * Build the `PreviewGame` GameLandingCombined actually renders, for one
 * game×location combo — the real "adapter/merge" step the brief calls for:
 *
 *   - game facts + art + reasons + illustrative reviews come from
 *     `PREVIEW_GAMES[family]` (the same fixture the live ~40 per-game pages
 *     use) — UNCHANGED, since those are genuinely game-specific, not
 *     location-specific.
 *   - REAL pricing replaces `PREVIEW_GAMES`' hardcoded `plans` entirely, built
 *     from live `GamePlan`/basePlan rows via `buildRealPreviewPlans` above —
 *     this is what keeps the known price-drift bug (PREVIEW_GAMES figures
 *     going stale vs the real GamePlan table, already hit once for palworld)
 *     from ever reappearing on the 615 game×location pages.
 *   - location-specific fields (`region`, `trustLatencyLabel`, `locationNote`,
 *     `fromPrice`) are overridden from this combo's real `GameLocationDef` —
 *     honesty framing reused VERBATIM from `loc.hub`, never re-templated.
 *
 * Returns `undefined` only if `family` has no `PREVIEW_GAMES` fixture at all
 * (shouldn't happen for anything in `ACTIVE_GAME_FAMILIES` — every family
 * there has an entry, Minecraft included as of 2026-09-19 — but the route
 * checks this and falls back rather than throwing if the two lists ever
 * drift apart again).
 */
export function buildGameLocationPreviewGame(combo: GameLocationCombo, cards: PlanCard[]): PreviewGame | undefined {
  const { location: loc, family } = combo;
  const base = PREVIEW_GAMES[family as PreviewGameKey] as PreviewGame | undefined;
  if (!base) return undefined;

  const plans = buildRealPreviewPlans(base.name, cards);
  const fromPrice = plans.length
    ? money(Math.min(...cards.map((p) => planIntroMonthlyCents(p) ?? p.priceCents)))
    : base.fromPrice;

  return {
    ...base,
    region: regionTagLabel(loc),
    fromPrice,
    plans: plans.length ? plans : base.plans,
    trustLatencyLabel: trustStripLabel(loc),
    locationNote: { flagCode: loc.flag, text: loc.hub },
  };
}

/** Deploy-wizard region hint for this combo's Deploy links, honest per `nearestRealRegion` above. */
export function gameLocationDeployRegion(combo: GameLocationCombo): string | undefined {
  return nearestRealRegion(combo.location);
}

/* ------------------------------------------------------------------ */
/* General "[Location] VPS/Game Server Hosting" pages — the locations   */

