71	 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
72	 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
73	 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
74	 * server is provisioned on), never a fabricated number.
75	 */
76	async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
77	  const plans = await db.gamePlan.findMany({
78	    where: { gameFamily, active: true },
79	    orderBy: { sortOrder: "asc" },
80	    include: { basePlan: true },
81	  });
82	  const rows: GamePlanRow[] = plans.map((p) => ({
83	    id: p.id,
84	    name: p.name,
85	    ramMB: p.ramMB,
86	    slots: p.slots,
87	    priceCents: p.priceCents,
