// Real-browser verification for the game×location GameLandingCombined rollout.
// Run with: node verify-gamelanding.mjs
import { chromium } from "playwright";
import fs from "fs";

const BASE = "https://staging.nxeon.cloud";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
fs.mkdirSync(OUT, { recursive: true });

const PAGES = [
  { slug: "rust-server-hosting", note: "reference — must be UNCHANGED" },
  { slug: "singapore-minecraft-server-hosting", note: "real-datacenter game combo" },
  { slug: "united-states-rust-server-hosting", note: "market-only game combo" },
  { slug: "north-america-vps-hosting", note: "general aggregate page — stays UseCaseLanding" },
  { slug: "south-korea-valheim-server-hosting", note: "network-presence game combo" },
];

const VIEWPORTS = [
  { name: "desktop", width: 1440, height: 900 },
  { name: "mobile", width: 390, height: 844 },
];

const results = [];

const browser = await chromium.launch();
for (const vp of VIEWPORTS) {
  const context = await browser.newContext({ viewport: { width: vp.width, height: vp.height } });
  const page = await context.newPage();
  for (const p of PAGES) {
    const url = `${BASE}/${p.slug}`;
    const rec = { url, viewport: vp.name, note: p.note };
    try {
      const resp = await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
      rec.status = resp?.status();
      await page.waitForTimeout(1200); // let animations/hydration settle
      const shotPath = `${OUT}/${p.slug}__${vp.name}.png`;
      await page.screenshot({ path: shotPath, fullPage: true });
      rec.screenshot = shotPath;

      // Text-content sanity checks
      const bodyText = await page.locator("body").innerText();
      rec.hasEmojiFlag = /[\u{1F1E6}-\u{1F1FF}]{2}/u.test(bodyText);
      rec.wordCount = bodyText.split(/\s+/).length;
      // Grammar/garbled-prose smell tests
      rec.hasBadDemonymArticle = /\ba American\b|\ba Indian\b|\ba English\b|\ba Australian\b/i.test(bodyText);
      rec.hasTunedForTemplateBug = /tuned for a [A-Z][a-z]+ audience/.test(bodyText);
    } catch (e) {
      rec.error = String(e);
    }
    results.push(rec);
    console.log(JSON.stringify(rec, null, 0));
  }
  await context.close();
}
await browser.close();

fs.writeFileSync(`${OUT}/results.json`, JSON.stringify(results, null, 2));
console.log("DONE");

