import { db } from "../lib/db";
import { findGameLocationCombo, buildGameLocationPreviewGame } from "../lib/marketing/gameLocationLandings";
import type { PlanCard } from "../components/marketing/PricingGrid";

async function main() {
  const combo = findGameLocationCombo("south-korea-valheim-server-hosting")!;
  const plans = await db.gamePlan.findMany({
    where: { gameFamily: combo.family, active: true },
    orderBy: { sortOrder: "asc" },
    include: { basePlan: true },
  });
  const cards: PlanCard[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: p.basePlan.bandwidthTB,
    priceCents: p.priceCents,
    storageTier: p.basePlan.storageTier,
    introMonthlyCents: p.introPriceCents,
    slots: p.slots,
  }));
  console.log("cards:", JSON.stringify(cards, null, 2));
  const preview = buildGameLocationPreviewGame(combo, cards);
  console.log("preview.plans:", JSON.stringify(preview?.plans, null, 2));
}
main().finally(() => db.$disconnect());

